function clean(v:any){return String(v||"").replace(/[\u2018\u2019]/g,"'").replace(/[\u2013\u2014]/g,"-").replace(/\s+/g," ").trim();}
function id(c:AnyRecord){return clean(c.id||c.candidate_id||c.email||c.phone||c.name||"unknown");}
