function uniq(a:string[]){return Array.from(new Set(a.map(clean).filter(Boolean)));}
function rxEsc(s:string){return s.replace(/[.*+?^${}()|[\]\\]/g,"\\$&");}
function has(rx:RegExp,t:string){return rx.test(t);}
function count(rx:RegExp,t:string){return Array.from(t.matchAll(new RegExp(rx.source, rx.flags.includes("g")?rx.flags:rx.flags+"g"))).length;}
function evidence(source:string,text:any){return {source,text:clean(text).slice(0,240)};}
