function sourcePrefixClean(name:string, raw:string, source:string, c:AnyRecord){let v=clean(name);const pref=v.match(/^(?:(?:Ams\s+)?(?:Ph|My|Sg|Vn)|Ams|Sap|Erp|Fi|Co|Sd|Mm|Pp|Pm|Ar|Asset|Btp)(?:\s+.+)$/i);if(!pref)return{value:v,reason:""};const candidate=cleanIdentityCandidate(sourcePrefixParts(v));const parts=candidate.toLowerCase().split(/\s+/).filter(Boolean);const support=[...emailLocalParts(raw,c),...linkedinLocalParts(raw,c)].join(" ");const labelled=/labelled_name/i.test(source);const header=/resume_header|contact_block/i.test(source);const emailSupport=parts.length>=2&&parts.some(p=>support.includes(p))&&parts.some(p=>support.includes(p.slice(0,4)));if((labelled||header)&&emailSupport)return{value:candidate,reason:""};if(labelled&&parts.length>=2)return{value:candidate,reason:""};return{value:v,reason:"source_or_module_prefix_name"};}
